    "selfCareTools.anxious3": "\u0915\u093f\u0938\u0940 \u092d\u0930\u094b\u0938\u0947\u092e\u0902\u0926 \u0935\u094d\u092f\u0915\u094d\u0924\u093f \u0938\u0947 \u0907\u0938 \u092c\u093e\u0930\u0947 \u092e\u0947\u0902 \u092c\u093e\u0924 \u0915\u0930\u0947\u0902, \u091a\u093e\u0939\u0947 \u091f\u0947\u0915\u094d\u0938\u094d\u091f \u0938\u0947 \u0939\u0940 \u0938\u0939\u0940",
    "selfCareTools.sad1": "\u0915\u0941\u091b \u092e\u093f\u0928\u091f \u0916\u0941\u0926 \u0915\u094b \u092f\u0939 \u092e\u0939\u0938\u0942\u0938 \u0915\u0930\u0928\u0947 \u0926\u0947\u0902, \u092c\u093f\u0928\u093e \u0909\u0938\u0947 \u0920\u0940\u0915 \u0915\u0930\u0928\u0947 \u0915\u0940 \u0915\u094b\u0936\u093f\u0936 \u0915\u093f\u090f",
    "selfCareTools.sad2": "\u0915\u094b\u0908 \u090f\u0915 \u091b\u094b\u091f\u0940 \u0938\u0940 \u0938\u0941\u0915\u0942\u0928 \u0926\u0947\u0928\u0947 \u0935\u093e\u0932\u0940 \u091a\u0940\u091c\u093c \u0915\u0930\u0947\u0902 - \u090f\u0915 \u0917\u0930\u094d\u092e \u0921\u094d\u0930\u093f\u0902\u0915, \u092a\u0938\u0902\u0926\u0940\u0926\u093e \u0917\u093e\u0928\u093e",
    "selfCareTools.sad3": "\u0915\u093f\u0938\u0940 \u090f\u0915 \u0935\u094d\u092f\u0915\u094d\u0924\u093f \u0938\u0947 \u0938\u0902\u092a\u0930\u094d\u0915 \u0915\u0930\u0947\u0902, \u091a\u093e\u0939\u0947 \u092c\u0938 \u0939\u093e\u092f \u0915\u0939\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0939\u0940 \u0938\u0939\u0940",
    "selfCareTools.angry1": "\u0915\u093f\u0938\u0940 \u092d\u0940 \u091a\u0940\u091c\u093c \u0915\u093e \u091c\u0935\u093e\u092c \u0926\u0947\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u0935\u0939\u093e\u0902 \u0938\u0947 \u0939\u091f \u091c\u093e\u090f\u0902",
