    "selfCareTools.tired1": "\u092c\u093f\u0928\u093e \u0915\u093f\u0938\u0940 \u0905\u092a\u0930\u093e\u0927\u092c\u094b\u0927 \u0915\u0947 \u0916\u0941\u0926 \u0915\u094b \u0906\u0930\u093e\u092e \u0915\u0930\u0928\u0947 \u0915\u0940 \u0907\u091c\u093e\u091c\u093c\u0924 \u0926\u0947\u0902",
