    "voiceToneAnalyzer.reasonVoiceUnstable": "\u0906\u0935\u093e\u091c\u093c \u0905\u0938\u094d\u0925\u093f\u0930 / \u0924\u0928\u093e\u0935\u0917\u094d\u0930\u0938\u094d\u0924",
    "voiceToneAnalyzer.noWordsDetected": "(\u0915\u094b\u0908 \u0936\u092c\u094d\u0926 \u0928\u0939\u0940\u0902 \u092e\u093f\u0932\u093e - \u092e\u093e\u0907\u0915 \u0915\u0947 \u092a\u093e\u0938 \u091c\u093c\u094b\u0930 \u0938\u0947 \u092c\u094b\u0932\u0947\u0902)",
    "voiceToneAnalyzer.helplineText": "\u091f\u0947\u0932\u0940-\u092e\u093e\u0928\u0938: {teleManas} | \u0915\u093f\u0930\u0923: {kiran}",
    "voiceToneAnalyzer.crisisAdvice": "\u0906\u092a\u0915\u0947 \u0936\u092c\u094d\u0926\u094b\u0902 \u0914\u0930 \u0906\u0935\u093e\u091c\u093c \u092e\u0947\u0902 \u0938\u0902\u0915\u091f \u0915\u0947 \u0938\u0902\u0915\u0947\u0924 \u0939\u0948\u0902\u0964 \u0915\u0943\u092a\u092f\u093e \u0905\u092d\u0940 {number} \u092a\u0930 \u0915\u0949\u0932 \u0915\u0930\u0947\u0902\u0964 \u0915\u093f\u0938\u0940 \u0905\u092a\u0928\u0947 \u0915\u0947 \u0938\u093e\u0925 \u0930\u0939\u0947\u0902\u0964",
