    "voiceToneAnalyzer.heading": "\u0935\u0949\u0907\u0938 \u0935\u0930\u094d\u0921 + \u091f\u094b\u0928 \u091c\u093e\u0902\u091a - Gemini \u0938\u0915\u094d\u0937\u092e",
    "voiceToneAnalyzer.subtitle": "\"no one will know if i die\" \u091c\u0948\u0938\u0947 \u0936\u092c\u094d\u0926\u094b\u0902 \u0915\u094b \u092a\u0939\u091a\u093e\u0928\u0924\u093e \u0939\u0948 + \u091f\u094b\u0928 \u091c\u093e\u0902\u091a\u0924\u093e \u0939\u0948 + Gemini \u0915\u0947 \u091c\u093c\u0930\u093f\u090f \u090f\u0928\u094d\u0915\u094d\u0930\u093f\u092a\u094d\u091f \u0915\u0930\u0915\u0947 \u0938\u0947\u0935 \u0915\u0930\u0924\u093e \u0939\u0948\u0964",
