    "themeAvatarSettings.pushBlocked": "\u0928\u094b\u091f\u093f\u092b\u093f\u0915\u0947\u0936\u0928 \u092c\u094d\u0932\u0949\u0915 \u0915\u0930 \u0926\u093f\u090f \u0917\u090f \u0925\u0947 - \u0906\u092a \u0907\u0928\u094d\u0939\u0947\u0902 \u0905\u092a\u0928\u0947 \u092c\u094d\u0930\u093e\u0909\u091c\u093c\u0930 \u0915\u0940 \u0938\u093e\u0907\u091f \u0938\u0947\u091f\u093f\u0902\u0917\u094d\u0938 \u092e\u0947\u0902 \u092b\u093f\u0930 \u0938\u0947 \u091a\u093e\u0932\u0942 \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964",
